/// The catalog entries the module contributes when enabled: the `model` type and `inference:invoke`.
pub fn inference_plugins(
    options: &crate::options::BetterIamOptions,
) -> IamResult<Vec<Arc<dyn better_iam_core::IamPlugin>>> {
    if options
        .inference
        .as_ref()
        .is_some_and(|toggle| toggle.enabled())
    {
        return Err(not_ported("inference.ts inferencePlugins"));
    }
    Ok(Vec::new())
}

